function vegIcon(key, size) {
  size = size || 88;
  const src = VEG_IMG[key] || VEG_IMG["tomato"];
  return `<img src="${src}" width="${size}" height="${size}" alt="${key}" style="object-fit:contain; display:block;">`;
}

