const cats = [
  "All",
  "Leafy Greens",
  "Root Vegetables",
  "Gourds & Squashes",
  "Exotic & Others",
  "Herbs & Aromatics",
];
let currentFilter = "All";

const chipsEl = document.getElementById("chips");
cats.forEach((c, i) => {
  const b = document.createElement("button");
  b.textContent = c;
  if (i === 0) b.classList.add("active");
  b.onclick = () => {
    document
      .querySelectorAll("#chips button")
      .forEach((x) => x.classList.remove("active"));
    b.classList.add("active");
    currentFilter = c;
    renderGrid(c, document.getElementById("search-input").value);
  };
  chipsEl.appendChild(b);
});

function renderGrid(filter, query) {
  filter = filter || "All";
  query = (query || "").toLowerCase().trim();
  const grid = document.getElementById("product-grid");
  grid.innerHTML = "";
  const list = products.filter(
    (p) =>
      (filter === "All" || p.cat === filter) &&
      (!query || p.name.toLowerCase().includes(query)),
  );
  document.getElementById("count-line").textContent =
    `Showing ${list.length} of ${products.length} vegetables`;
  list.forEach((p) => {
    const el = document.createElement("div");
    el.className = "card p-card";
    el.onclick = () => openProduct(p);
    el.innerHTML = `
      <span class="organic-badge">FRESH</span>
      <div class="p-thumb" style="background:${p.bg}">${vegIcon(p.key, 78)}</div>
      <div class="p-name">${p.name}</div>
      <div class="p-vendor">${p.vendor}</div>
      <div class="p-row">
        <div><div class="p-price">₹${p.price}/${p.unit}</div><div class="p-rating">★ ${p.rating}</div></div>
        <button class="add-btn" onclick="event.stopPropagation();addToCart('${p.key}',1);showToast('${p.name} added to basket')">+</button>
      </div>`;
    grid.appendChild(el);
  });
}
renderGrid("All", "");

/*   Product detail page   */
let currentProduct = null,
  currentQty = 1,
  currentPackMult = 1;
function openProduct(p) {
  currentProduct = p;
  currentQty = 1;
  currentPackMult = 1;
  document.getElementById("qty-val").textContent = 1;
  document
    .querySelectorAll("#product-packs .pack")
    .forEach((el, i) => el.classList.toggle("selected", i === 1));
  document.getElementById("product-title").textContent = p.name;
  document.getElementById("product-vendor-pill").textContent =
    `Sold by ${p.vendor} · 4.8★ seller`;
  document.getElementById("product-meta").textContent =
    `★ ${p.rating} · Harvested within 24 hours`;
  document.getElementById("product-price").textContent =
    `₹${p.price} / ${p.unit}`;
  document.getElementById("product-hero-img").style.background = p.bg;
  document.getElementById("product-hero-img").innerHTML = vegIcon(p.key, 220);
  showView("product");
}
function selectPack(el) {
  document
    .querySelectorAll(".pack")
    .forEach((x) => x.classList.remove("selected"));
  el.classList.add("selected");
  currentPackMult =
    el.textContent === "Half" ? 0.5 : el.textContent === "Double" ? 2 : 1;
}
function changeProductQty(delta) {
  currentQty = Math.max(1, currentQty + delta);
  document.getElementById("qty-val").textContent = currentQty;
}
function addCurrentToCart(goCheckout) {
  if (!currentProduct) return;
  addToCart(currentProduct.key, currentQty * currentPackMult);
  showToast(`${currentProduct.name} added to basket`);
  showView("cart");
}

/*  
       CART — fully functional add / remove / quantity / live totals
      */
let cart = [
  { key: "tomato", mult: 2 },
  { key: "spinach", mult: 3 },
  { key: "carrot", mult: 1 },
];

function findProduct(key) {
  return products.find((p) => p.key === key);
}

function addToCart(key, mult) {
  mult = mult || 1;
  const existing = cart.find((c) => c.key === key);
  if (existing) {
    existing.mult += mult;
  } else {
    cart.push({ key, mult });
  }
  renderCart();
}
function removeFromCart(key) {
  cart = cart.filter((c) => c.key !== key);
  renderCart();
  showToast("Item removed from basket");
}
function changeCartQty(key, delta) {
  const item = cart.find((c) => c.key === key);
  if (!item) return;
  item.mult = Math.max(1, Math.round((item.mult + delta * 1) * 10) / 10);
  renderCart();
}

function renderCart() {
  const wrap = document.getElementById("cart-items");
  const subtitle = document.getElementById("cart-subtitle");
  const checkoutBtn = document.getElementById("checkout-btn");
  wrap.innerHTML = "";

  if (cart.length === 0) {
    subtitle.textContent = "Your basket is empty";
    wrap.innerHTML = `<div class="card empty-cart">
      <div style="font-size:15px; font-weight:700; margin-bottom:6px;">Your basket is empty</div>
      <div style="font-size:13px; margin-bottom:18px;">Add some fresh vegetables to get started.</div>
      <button class="btn solid" onclick="showView('home')">Browse Vegetables</button>
    </div>`;
    checkoutBtn.disabled = true;
    checkoutBtn.style.opacity = 0.5;
  } else {
    subtitle.textContent = `${cart.length} item${cart.length > 1 ? "s" : ""} in your basket`;
    checkoutBtn.disabled = false;
    checkoutBtn.style.opacity = 1;
    cart.forEach((c) => {
      const p = findProduct(c.key);
      if (!p) return;
      const lineTotal = Math.round(p.price * c.mult);
      const div = document.createElement("div");
      div.className = "card cart-item";
      div.innerHTML = `
        <div class="cart-thumb" style="background:${p.bg}">${vegIcon(p.key, 40)}</div>
        <div class="info">
          <div style="font-weight:700; font-size:14px;">${p.name}</div>
          <div class="muted" style="font-size:11px;">₹${p.price}/${p.unit}</div>
          <div class="iqty">
            <button onclick="changeCartQty('${c.key}',-1)">–</button>
            <span style="font-weight:700; font-size:13px;">${c.mult} ${p.unit}</span>
            <button onclick="changeCartQty('${c.key}',1)">+</button>
          </div>
        </div>
        <div style="display:flex; flex-direction:column; align-items:flex-end; gap:10px;">
          <div class="p-price">₹${lineTotal}</div>
          <button class="remove-box" onclick="removeFromCart('${c.key}')" title="Remove ${p.name}">
            <svg width="16" height="16" viewBox="0 0 24 24" fill="none"><path d="M4 7h16M9 7V5a2 2 0 0 1 2-2h2a2 2 0 0 1 2 2v2m-9 0 1 13a2 2 0 0 0 2 2h6a2 2 0 0 0 2-2l1-13" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"/></svg>
            <span class="rb-label">REMOVE</span>
          </button>
        </div>`;
      wrap.appendChild(div);
    });
  }

  const subtotal = cart.reduce((sum, c) => {
    const p = findProduct(c.key);
    return sum + (p ? p.price * c.mult : 0);
  }, 0);
  const tax = Math.round(subtotal * 0.02);
  const total = Math.round(subtotal + tax);
  document.getElementById("sum-subtotal").textContent =
    `₹${Math.round(subtotal)}`;
  document.getElementById("sum-tax").textContent = `₹${tax}`;
  document.getElementById("sum-total").textContent = `₹${total}`;
  document.getElementById("cart-count").textContent = cart.length;
}
renderCart();

function computeCartTotals() {
  const subtotal = cart.reduce((sum, c) => {
    const p = findProduct(c.key);
    return sum + (p ? p.price * c.mult : 0);
  }, 0);
  const tax = Math.round(subtotal * 0.02);
  const total = Math.round(subtotal + tax);
  return { subtotal: Math.round(subtotal), tax, total };
}

/*  
       CHECKOUT — editable delivery address + Cash on Delivery / Online payment
      */
let deliveryAddress = {
  name: "Ravi King",
  phone: "+91 98765 43210",
  line: "221B, MG Road, Banjara Hills",
  city: "Hyderabad",
  pincode: "500034",
};
let paymentMethod = "cod";
let onlineSubMethod = "upi";

function renderAddressDisplay() {
  const a = deliveryAddress;
  document.getElementById("addr-display").innerHTML = `
    <div class="addr-line">
      <div class="addr-name">${a.name}</div>
      ${a.line}, ${a.city} - ${a.pincode}<br>
      Phone: ${a.phone}
    </div>`;
}
function toggleEditAddress() {
  const form = document.getElementById("addr-form");
  const display = document.getElementById("addr-display");
  const showingForm = form.style.display !== "none";
  if (showingForm) {
    form.style.display = "none";
    display.style.display = "block";
    document.getElementById("addr-edit-toggle").textContent = "Edit";
  } else {
    document.getElementById("addr-name").value = deliveryAddress.name;
    document.getElementById("addr-phone").value = deliveryAddress.phone;
    document.getElementById("addr-line").value = deliveryAddress.line;
    document.getElementById("addr-city").value = deliveryAddress.city;
    document.getElementById("addr-pincode").value = deliveryAddress.pincode;
    form.style.display = "block";
    display.style.display = "none";
    document.getElementById("addr-edit-toggle").textContent = "Cancel";
  }
}
function saveAddress() {
  deliveryAddress = {
    name: document.getElementById("addr-name").value || deliveryAddress.name,
    phone: document.getElementById("addr-phone").value || deliveryAddress.phone,
    line: document.getElementById("addr-line").value || deliveryAddress.line,
    city: document.getElementById("addr-city").value || deliveryAddress.city,
    pincode:
      document.getElementById("addr-pincode").value || deliveryAddress.pincode,
  };
  renderAddressDisplay();
  document.getElementById("addr-form").style.display = "none";
  document.getElementById("addr-display").style.display = "block";
  document.getElementById("addr-edit-toggle").textContent = "Edit";
  showToast("Delivery address updated");
}

function selectPayment(method) {
  paymentMethod = method;
  document
    .getElementById("pay-cod")
    .classList.toggle("selected", method === "cod");
  document
    .getElementById("pay-online")
    .classList.toggle("selected", method === "online");
  document.getElementById("online-details").style.display =
    method === "online" ? "block" : "none";
}
function selectOnlineSub(sub) {
  onlineSubMethod = sub;
  ["upi", "card", "netbanking"].forEach((s) =>
    document.getElementById("om-" + s).classList.toggle("active", s === sub),
  );
  const field = document.getElementById("online-field-input");
  if (sub === "upi")
    field.innerHTML = `<input type="text" id="upi-id" placeholder="yourname@upi">`;
  else if (sub === "card")
    field.innerHTML = `<input type="text" id="card-number" placeholder="Card number (•••• •••• •••• ••••)">`;
  else
    field.innerHTML = `<input type="text" id="bank-name" placeholder="Select your bank">`;
}

function renderCheckout() {
  if (cart.length === 0) {
    showView("cart");
    return;
  }
  renderAddressDisplay();
  document.getElementById("addr-form").style.display = "none";
  document.getElementById("addr-display").style.display = "block";
  document.getElementById("addr-edit-toggle").textContent = "Edit";

  const itemsBox = document.getElementById("checkout-items");
  itemsBox.innerHTML = "";
  cart.forEach((c) => {
    const p = findProduct(c.key);
    if (!p) return;
    const row = document.createElement("div");
    row.className = "summary-row";
    row.innerHTML = `<span>${p.name} (${c.mult} ${p.unit})</span><span>₹${Math.round(p.price * c.mult)}</span>`;
    itemsBox.appendChild(row);
  });
  const t = computeCartTotals();
  document.getElementById("co-subtotal").textContent = `₹${t.subtotal}`;
  document.getElementById("co-tax").textContent = `₹${t.tax}`;
  document.getElementById("co-total").textContent = `₹${t.total}`;
}

function placeOrder() {
  if (cart.length === 0) return;

  const box = document.getElementById("track-order-items");
  box.innerHTML =
    '<strong style="font-size:13px;">Items in this delivery</strong>';
  cart.forEach((c) => {
    const p = findProduct(c.key);
    if (!p) return;
    const row = document.createElement("div");
    row.className = "oi-row";
    row.innerHTML = `<span>${p.name} — ${c.mult} ${p.unit}</span><span>₹${Math.round(p.price * c.mult)}</span>`;
    box.appendChild(row);
  });

  const addrBox = document.getElementById("track-address-box");
  const a = deliveryAddress;
  addrBox.innerHTML = `<strong style="font-size:13px;">Delivery Address</strong>
    <div class="oi-row" style="display:block; padding-top:8px;">
      <div style="font-weight:700;">${a.name}</div>
      <div class="muted">${a.line}, ${a.city} - ${a.pincode}</div>
      <div class="muted">Phone: ${a.phone}</div>
    </div>`;

  const payBox = document.getElementById("track-payment-box");
  let payText = "Cash on Delivery";
  if (paymentMethod === "online") {
    payText =
      onlineSubMethod === "upi"
        ? "Online Payment — UPI"
        : onlineSubMethod === "card"
          ? "Online Payment — Card"
          : "Online Payment — Net Banking";
  }
  const t = computeCartTotals();
  payBox.innerHTML = `<strong style="font-size:13px;">Payment Method</strong>
    <div class="oi-row"><span>${payText}</span><span style="font-weight:700;">₹${t.total}</span></div>`;

  document.getElementById("track-order-id").textContent =
    "Order #FM-" + (5500 + Math.floor(Math.random() * 400));
  showToast("Order placed! Tracking your delivery...");
  showView("tracking");
}

