/*  
       NAVIGATION — a persistent header Back button always returns Home
      */
function showView(id) {
  document
    .querySelectorAll(".view")
    .forEach((v) => v.classList.remove("active"));
  document.getElementById(id).classList.add("active");
  document
    .querySelectorAll("nav.tabs button")
    .forEach((b) => b.classList.toggle("active", b.dataset.view === id));
  document
    .getElementById("global-back")
    .classList.toggle("show", id !== "home");
  closeAccountMenu();
  window.scrollTo({ top: 0, behavior: "smooth" });
}
document.querySelectorAll("nav.tabs button").forEach((b) => {
  b.addEventListener("click", () => showView(b.dataset.view));
});

/*   Auth state & account menu   */
let session = {
  loggedIn: false,
  name: "Anita Rao",
  email: "anita.rao@example.com",
};
function initials(name) {
  return name
    .split(" ")
    .map((w) => w[0])
    .join("")
    .slice(0, 2)
    .toUpperCase();
}
function renderAccountButton() {
  document.getElementById("avatar-sm").textContent = session.loggedIn
    ? initials(session.name)
    : "?";
  document.getElementById("account-label").textContent = session.loggedIn
    ? session.name.split(" ")[0]
    : "Sign in";
}
function renderAccountMenu() {
  const menu = document.getElementById("account-menu");
  if (session.loggedIn) {
    menu.innerHTML = `
      <div class="who"><div class="name">${session.name}</div><div class="email">${session.email}</div></div>
      <button onclick="showView('tracking')">My Orders</button>
      <button onclick="showView('vendor')">Seller Portal</button>
      <button onclick="showView('verify-otp')">Change Password</button>
      <hr><button class="danger" onclick="handleLogout()">Log Out</button>`;
  } else {
    menu.innerHTML = `
      <button onclick="showView('login')">Sign In</button>
      <button onclick="showView('signup')">Create Account</button>
      <button onclick="showView('verify-otp')">Forgot Password</button>`;
  }
}
function toggleAccountMenu(e) {
  e.stopPropagation();
  renderAccountMenu();
  document.getElementById("account-menu").classList.toggle("open");
}
function closeAccountMenu() {
  document.getElementById("account-menu").classList.remove("open");
}
document.addEventListener("click", closeAccountMenu);

function showToast(msg) {
  const t = document.getElementById("toast");
  document.getElementById("toast-msg").textContent = msg;
  t.classList.add("show");
  setTimeout(() => t.classList.remove("show"), 2400);
}
function handleLogin() {
  session.loggedIn = true;
  renderAccountButton();
  showToast("Signed in as " + session.name);
  showView("home");
}
function handleLogout() {
  session.loggedIn = false;
  renderAccountButton();
  closeAccountMenu();
  showToast("You have been logged out");
  showView("home");
}
function fakeOAuth(provider) {
  showToast("Connecting to " + provider + "...");
  setTimeout(handleLogin, 700);
}
function startEmailVerification() {
  const emailInput = document.getElementById("signup-email");
  document.getElementById("verify-email-addr").textContent =
    (emailInput && emailInput.value) || "you@example.com";
  showView("verify-email");
}
function finishEmailVerification() {
  showToast("Email verified successfully");
  handleLogin();
}
function resendCode() {
  showToast("Verification code resent");
}

document.querySelectorAll(".otp-row").forEach((row) => {
  const boxes = row.querySelectorAll(".otp-box");
  boxes.forEach((box, i) => {
    box.addEventListener("input", () => {
      box.value = box.value.replace(/[^0-9]/g, "");
      if (box.value && boxes[i + 1]) boxes[i + 1].focus();
    });
    box.addEventListener("keydown", (e) => {
      if (e.key === "Backspace" && !box.value && boxes[i - 1])
        boxes[i - 1].focus();
    });
  });
});

function updateStrength(val, suffix) {
  suffix = suffix || "";
  const ids = ["s1" + suffix, "s2" + suffix, "s3" + suffix, "s4" + suffix];
  const labelId = "strength-label" + (suffix ? "-b" : "");
  const bars2 = ids.map((id) => document.getElementById(id)).filter(Boolean);
  let score = 0;
  if (val.length >= 8) score++;
  if (/[0-9]/.test(val)) score++;
  if (/[^A-Za-z0-9]/.test(val)) score++;
  if (/[A-Z]/.test(val) && /[a-z]/.test(val)) score++;
  const colors = [
    "var(--border)",
    "#c8493c",
    "var(--warn)",
    "var(--teal)",
    "var(--success)",
  ];
  const labels = ["Weak", "Weak", "Fair", "Good", "Strong"];
  bars2.forEach(
    (b, i) =>
      (b.style.background = i < score ? colors[score] : "var(--border)"),
  );
  const lbl = document.getElementById(labelId);
  if (lbl) lbl.textContent = labels[score];
}

